package local.pocketchat;

import org.json.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;

/** Actual candidate/snapshot/export chain. Fingerprint strings are identity
 * fixtures, never a claim that a native core calculated or verified them. */
public final class NetworkShareSnapshotTest {
  static JSONArray checks=new JSONArray();
  static final String FP="1".repeat(64),OTHER_FP="2".repeat(64),PRIVATE="SYNTHETIC-PRIVATE-CREDENTIAL";
  static byte[] bytes(String text){return text.getBytes(StandardCharsets.UTF_8);}
  static void check(String label,boolean pass){checks.put(J.obj("name",label,"pass",pass));if(!pass)throw new AssertionError(label);}
  static JSONObject detail(String name){return J.obj("name",name,"type","Socks5","configFingerprint",FP,"configFingerprintVersion",1);}
  static String source(String password){return "unrelated: {account: NEVER-EXPORT-UNRELATED}\nproxies: [{name: Selected, type: socks5, server: 127.0.0.1, port: 1080, password: '"+password+"'}]\n";}
  static JSONObject row(JSONArray rows,String name)throws Exception{for(int i=0;i<rows.length();i++)if(name.equals(rows.getJSONObject(i).optString("name")))return rows.getJSONObject(i);throw new AssertionError("Missing row "+name);}
  static boolean candidate(JSONObject row){return row.optJSONObject("shareCandidate")!=null&&"candidate".equals(row.optString("shareAvailability"));}
  static void requireHidden(JSONArray details,String label){String text=details.toString();check(label,!text.contains(PRIVATE)&&!text.contains("shareCandidate")&&!text.contains("shareSourceHash")&&!text.contains("shareVersion")&&!text.contains("NEVER-EXPORT-UNRELATED"));}
  public static void main(String[] args)throws Exception{
    byte[] raw=bytes(source(PRIVATE));JSONArray metadata=J.arr(detail("Entry|Selected"));JSONArray ready=NetworkShareCodec.candidates(raw,NetworkCatalog.ENTRY,metadata);JSONObject readyRow=ready.getJSONObject(0);
    check("Production candidates bind exact source hash and snapshot version",candidate(readyRow)&&readyRow.getString("shareSourceHash").equals(NetworkShareSnapshot.hash(raw))&&readyRow.getInt("shareVersion")==NetworkShareSnapshot.VERSION);
    check("Candidate construction never mutates native metadata",!metadata.getJSONObject(0).has("shareCandidate")&&!metadata.toString().contains(PRIVATE));
    NetworkShareSnapshot.Parts split=NetworkShareSnapshot.split(ready,raw);requireHidden(split.details,"Private candidate values are absent from public node details");
    check("Private sidecar retains selected credentials only",split.index!=null&&new String(split.index,StandardCharsets.UTF_8).contains(PRIVATE)&&!new String(split.index,StandardCharsets.UTF_8).contains("NEVER-EXPORT-UNRELATED"));
    check("Split does not mutate parser-worker candidates",ready.getJSONObject(0).has("shareCandidate"));
    JSONObject selected=NetworkShareSnapshot.select(split.index,raw,"Entry|Selected",FP);JSONObject validated=NetworkShareCodec.node(selected,false);byte[] exported=NetworkShareCodec.provider(validated);JSONObject reparsed=NetworkShareCodec.extract(exported,"Entry|Selected",NetworkCatalog.ENTRY);
    check("Actual candidate to split to select to node/provider chain preserves credential",reparsed.getString("password").equals(PRIVATE)&&reparsed.getInt("port")==1080);
    selected.put("password","caller-mutated");check("Returned selected candidate is detached from saved sidecar",NetworkShareSnapshot.select(split.index,raw,"Entry|Selected",FP).getString("password").equals(PRIVATE));
    check("Source-byte changes invalidate candidate even when semantic node is unchanged",NetworkShareSnapshot.select(split.index,bytes(source(PRIVATE)+"# new refresh\n"),"Entry|Selected",FP)==null);
    check("Native identity mismatch cannot select same-name candidate",NetworkShareSnapshot.select(split.index,raw,"Entry|Selected",OTHER_FP)==null);
    check("Invalid or missing fingerprint cannot select candidate",NetworkShareSnapshot.select(split.index,raw,"Entry|Selected","short")==null&&NetworkShareSnapshot.select(split.index,raw,"Entry|Selected",null)==null);
    check("Role-prefixed names do not cross select",NetworkShareSnapshot.select(split.index,raw,"Exit|Selected",FP)==null);
    JSONObject future=new JSONObject(new String(split.index,StandardCharsets.UTF_8));future.put("version",NetworkShareSnapshot.VERSION+1);check("Unknown snapshot version is refused",NetworkShareSnapshot.select(bytes(future.toString()),raw,"Entry|Selected",FP)==null);
    for(String mismatch:new String[]{"source","candidate-version","native-version","native-fingerprint"}){
      JSONArray wrong=new JSONArray(ready.toString());JSONObject item=wrong.getJSONObject(0);
      if(mismatch.equals("source"))item.put("shareSourceHash","f".repeat(64));else if(mismatch.equals("candidate-version"))item.put("shareVersion",NetworkShareSnapshot.VERSION+1);else if(mismatch.equals("native-version"))item.put("configFingerprintVersion",2);else item.put("configFingerprint","bad");
      NetworkShareSnapshot.Parts rejected=NetworkShareSnapshot.split(wrong,raw);check("Split rejects "+mismatch+" binding",rejected.index==null&&rejected.details.getJSONObject(0).optString("shareAvailability").equals("unavailable"));requireHidden(rejected.details,"Rejected "+mismatch+" candidate stays private");
    }
    StringBuilder aliases=new StringBuilder("base: &defaults {type: socks5, server: 127.0.0.1, port: 1080, password: "+PRIVATE+"}\nmetadata: !!java.net.URL [NEVER-EXPORT-UNRELATED]\nproxies:\n");JSONArray all=new JSONArray();
    for(int i=0;i<100;i++){aliases.append("  - {<<: *defaults, name: Node-").append(i).append("}\n");all.put(detail("Entry|Node-"+i));}
    byte[] many=bytes(aliases.toString());JSONArray manyReady=NetworkShareCodec.candidates(many,NetworkCatalog.ENTRY,all);NetworkShareSnapshot.Parts manySplit=NetworkShareSnapshot.split(manyReady,many);
    check("One composed 100-alias subscription produces all 100 candidates",manyReady.length()==100&&candidate(row(manyReady,"Entry|Node-0"))&&candidate(row(manyReady,"Entry|Node-99"))&&new JSONObject(new String(manySplit.index,StandardCharsets.UTF_8)).getJSONObject("nodes").length()==100);
    requireHidden(manySplit.details,"100-alias metadata exposes no credentials or unrelated custom tags");
    byte[] lastExport=NetworkShareCodec.provider(NetworkShareCodec.node(NetworkShareSnapshot.select(manySplit.index,many,"Entry|Node-99",FP),false));check("Selected alias snapshot exports only that node",new String(lastExport,StandardCharsets.UTF_8).contains("Node-99")&&!new String(lastExport,StandardCharsets.UTF_8).contains("Node-0"));
    String mixed="proxies:\n - {name: Unsupported, type: ssh, server: 127.0.0.1, port: 22, username: synthetic}\n - {name: Oversize, type: socks5, server: 127.0.0.1, port: 1080, password: '"+"x".repeat(8193)+"'}\n - {name: Good, type: socks5, server: 127.0.0.1, port: 1080}\n";
    JSONArray mixedReady=NetworkShareCodec.candidates(bytes(mixed),NetworkCatalog.ENTRY,J.arr(detail("Entry|Unsupported"),detail("Entry|Oversize"),detail("Entry|Good")));
    check("Unsupported or oversized standalone nodes do not block a later supported node",!candidate(row(mixedReady,"Entry|Unsupported"))&&!candidate(row(mixedReady,"Entry|Oversize"))&&candidate(row(mixedReady,"Entry|Good")));
    NetworkShareSnapshot.Parts mixedSplit=NetworkShareSnapshot.split(mixedReady,bytes(mixed));check("Sidecar includes only independently eligible node",new JSONObject(new String(mixedSplit.index,StandardCharsets.UTF_8)).getJSONObject("nodes").length()==1&&NetworkShareSnapshot.select(mixedSplit.index,bytes(mixed),"Entry|Good",FP)!=null);
    String lookupFailure="proxies: [{name: Bad, type: socks5, server: 127.0.0.1, port: 1080, password: first, password: second}, {name: Good, type: socks5, server: 127.0.0.1, port: 1080}]\n";
    JSONArray isolated=NetworkShareCodec.candidates(bytes(lookupFailure),NetworkCatalog.ENTRY,J.arr(detail("Entry|Bad"),detail("Entry|Good")));check("A per-node name lookup failure cannot erase another candidate",!candidate(row(isolated,"Entry|Bad"))&&candidate(row(isolated,"Entry|Good")));
    StringBuilder inherited=new StringBuilder("bad0: &bad0 {<<: *bad0}\n");for(int i=1;i<=48;i++)inherited.append("bad").append(i).append(": &bad").append(i).append(" {<<: *bad").append(i-1).append("}\n");inherited.append("proxies:\n");for(int i=0;i<3000;i++)inherited.append(" - {<<: *bad48}\n");inherited.append(" - {name: NamedTail, type: socks5, server: 127.0.0.1, port: 1080}\n");byte[] inheritedBytes=bytes(inherited.toString());
    JSONArray inheritedReady=NetworkShareCodec.candidates(inheritedBytes,NetworkCatalog.ENTRY,J.arr(detail("Entry|NamedTail")));check("Exhausted unrelated inherited-name walks cannot hide a direct selected name",candidate(inheritedReady.getJSONObject(0))&&NetworkShareCodec.extract(inheritedBytes,"Entry|NamedTail",NetworkCatalog.ENTRY).getInt("port")==1080);
    String duplicate="proxies: [{name: Duplicate, type: socks5, server: 127.0.0.1, port: 1080}, {name: Duplicate, type: socks5, server: 127.0.0.2, port: 1081}, {name: Good, type: socks5, server: 127.0.0.1, port: 1080}]\n";
    JSONArray duplicateReady=NetworkShareCodec.candidates(bytes(duplicate),NetworkCatalog.ENTRY,J.arr(detail("Entry|Duplicate"),detail("Entry|Good")));check("Duplicate selected names are refused without blocking a distinct name",!candidate(row(duplicateReady,"Entry|Duplicate"))&&candidate(row(duplicateReady,"Entry|Good")));
    byte[] oversized=new byte[16*1024*1024+1];JSONArray limited=NetworkShareCodec.candidates(oversized,NetworkCatalog.ENTRY,metadata);check("Oversized whole subscription has no candidate",!candidate(limited.getJSONObject(0))&&limited.getJSONObject(0).getString("shareAvailability").equals("unsupported-format"));
    JSONArray repeated=new JSONArray();for(int i=0;i<4097;i++)repeated.put(detail("Entry|Selected"));JSONArray bounded=NetworkShareCodec.candidates(raw,NetworkCatalog.ENTRY,repeated);check("Per-refresh candidate count is bounded at 4096",candidate(bounded.getJSONObject(4095))&&!candidate(bounded.getJSONObject(4096))&&bounded.getJSONObject(4096).optString("shareAvailability").equals("budget"));
    StringBuilder aggregate=new StringBuilder("defaults: &large {type: socks5, server: 127.0.0.1, port: 1080, password: '"+"p".repeat(7000)+"'}\nproxies:\n");JSONArray aggregateMetadata=new JSONArray();
    for(int i=0;i<1400;i++){aggregate.append(" - {<<: *large, name: Budget-").append(i).append("}\n");aggregateMetadata.put(detail("Entry|Budget-"+i));}
    byte[] aggregateBytes=bytes(aggregate.toString());JSONArray aggregateReady=NetworkShareCodec.candidates(aggregateBytes,NetworkCatalog.ENTRY,aggregateMetadata);int acceptedCount=0;for(int i=0;i<aggregateReady.length();i++)if(candidate(aggregateReady.getJSONObject(i)))acceptedCount++;
    check("Expanded candidate byte budget stops shared-alias payload growth",acceptedCount>0&&acceptedCount<aggregateReady.length()&&candidate(aggregateReady.getJSONObject(0))&&!candidate(aggregateReady.getJSONObject(1399)));
    NetworkShareSnapshot.Parts aggregateSplit=NetworkShareSnapshot.split(aggregateReady,aggregateBytes);check("Bounded candidates produce a bounded private sidecar",aggregateSplit.index!=null&&aggregateSplit.index.length<=NetworkShareSnapshot.LIMIT&&!aggregateSplit.details.toString().contains("pppppppp"));
    StringBuilder longSource=new StringBuilder("proxies:\n");JSONArray longMetadata=new JSONArray();for(int i=0;i<4097;i++){longSource.append(" - {name: Tail-").append(i).append(", type: socks5, server: 127.0.0.1, port: 1080}\n");longMetadata.put(detail("Entry|Tail-"+i));}byte[] longBytes=bytes(longSource.toString());JSONArray longReady=NetworkShareCodec.candidates(longBytes,NetworkCatalog.ENTRY,longMetadata);
    check("A valid node beyond cache count limit is marked budget rather than unsupported",longReady.getJSONObject(4096).optString("shareAvailability").equals("budget")&&!candidate(longReady.getJSONObject(4096)));
    JSONObject tail=NetworkShareCodec.extract(longBytes,"Entry|Tail-4096",NetworkCatalog.ENTRY);check("Uncached late node retains bounded on-demand extract/provider fallback",NetworkShareCodec.extract(NetworkShareCodec.provider(tail),"Entry|Tail-4096",NetworkCatalog.ENTRY).getInt("port")==1080);
    StringBuilder expanded=new StringBuilder("defaults: &defaults {type: vless, server: 127.0.0.1, port: 443, uuid: 00000000-0000-0000-0000-000000000001, network: ws, ws-opts: {headers: {");for(int i=0;i<40;i++){if(i>0)expanded.append(',');expanded.append("X-").append(i).append(": value");}expanded.append("}}}\nproxies:\n");JSONArray expandedMetadata=new JSONArray();for(int i=0;i<3000;i++){expanded.append(" - {<<: *defaults, name: Expanded-").append(i).append("}\n");expandedMetadata.put(detail("Entry|Expanded-"+i));}expanded.append(" - {name: AfterBudget, type: socks5, server: 127.0.0.1, port: 1080}\n");expandedMetadata.put(detail("Entry|AfterBudget"));byte[] expandedBytes=bytes(expanded.toString());JSONArray expandedReady=NetworkShareCodec.candidates(expandedBytes,NetworkCatalog.ENTRY,expandedMetadata);
    check("Expanded-construction budget does not label trailing simple node unsupported",expandedReady.getJSONObject(3000).optString("shareAvailability").equals("budget")&&!candidate(expandedReady.getJSONObject(3000)));
    check("Fresh selected-node fallback succeeds after optional index construction budget is exhausted",NetworkShareCodec.extract(expandedBytes,"Entry|AfterBudget",NetworkCatalog.ENTRY).getInt("port")==1080);
    check("Oversized sidecar cannot be selected",NetworkShareSnapshot.select(new byte[NetworkShareSnapshot.LIMIT+1],raw,"Entry|Selected",FP)==null);
    JSONArray legacy=NetworkShareCodec.candidates(bytes("c29ja3M1Oi8vc3ludGhldGljCg=="),NetworkCatalog.ENTRY,metadata);NetworkShareSnapshot.Parts noIndex=NetworkShareSnapshot.split(legacy,raw);check("Unsupported URI/Base64 source advertises limits and has no sidecar",legacy.getJSONObject(0).getString("shareAvailability").equals("unsupported-format")&&noIndex.index==null);
    // The complete source is accepted by upstream Mihomo: ordinary nodes first
    // keep its alias ratio bounded. Rejected candidates still spend real visits.
    StringBuilder rejectedWork=new StringBuilder("defaults: &large {type: socks5, server: 127.0.0.1, port: 1080, ignored-field: [");for(int i=0;i<8200;i++){if(i>0)rejectedWork.append(',');rejectedWork.append('v');}rejectedWork.append("]}\nproxies:\n");JSONArray rejectedMetadata=new JSONArray();
    for(int i=0;i<4000;i++){rejectedWork.append(" - {name: Filler-").append(i).append(", type: socks5, server: 127.0.0.1, port: 1080}\n");rejectedMetadata.put(detail("Entry|Filler-"+i));}
    for(int i=0;i<40;i++){rejectedWork.append(" - {<<: *large, name: Rejected-").append(i).append("}\n");rejectedMetadata.put(detail("Entry|Rejected-"+i));}rejectedWork.append(" - {name: RejectedTail, type: socks5, server: 127.0.0.1, port: 1080}\n");rejectedMetadata.put(detail("Entry|RejectedTail"));byte[] rejectedBytes=bytes(rejectedWork.toString());
    NetworkShareCodec.Source spent=new NetworkShareCodec.Source(rejectedBytes);for(int i=0;i<4000;i++)spent.select("Entry|Filler-"+i,NetworkCatalog.ENTRY);int beforeFailures=spent.remaining,failedCandidates=0;
    for(int i=0;i<40;i++)try{spent.select("Entry|Rejected-"+i,NetworkCatalog.ENTRY);}catch(NetworkShareCodec.BudgetFailure expected){failedCandidates++;}
    check("Failed selected-node traversals consume cumulative construction budget",failedCandidates==40&&spent.remaining<beforeFailures&&spent.remaining==-1);
    int afterFailures=spent.remaining;boolean alreadySpent=false;try{spent.select("Entry|RejectedTail",NetworkCatalog.ENTRY);}catch(NetworkShareCodec.BudgetFailure expected){alreadySpent=true;}check("Exhausted candidate source refuses another traversal without spending more visits",alreadySpent&&spent.remaining==afterFailures);
    JSONArray rejectedReady=NetworkShareCodec.candidates(rejectedBytes,NetworkCatalog.ENTRY,rejectedMetadata);JSONObject rejectedTail=row(rejectedReady,"Entry|RejectedTail");check("Rejected-node work marks later cache candidates as budget",!candidate(rejectedTail)&&rejectedTail.optString("shareAvailability").equals("budget"));
    check("Rejected-node cache budget leaves selected-node fallback available",NetworkShareCodec.extract(rejectedBytes,"Entry|RejectedTail",NetworkCatalog.ENTRY).getInt("port")==1080);
    NetworkShareCodec.Source clipped=new NetworkShareCodec.Source(raw);clipped.remaining=3;boolean clippedFailure=false;try{clipped.select("Entry|Selected",NetworkCatalog.ENTRY);}catch(NetworkShareCodec.BudgetFailure expected){clippedFailure=true;}check("Selected traversal respects the final cumulative allowance including the failing visit",clippedFailure&&clipped.remaining==-1);
    NetworkShareCodec.Source cyclic=new NetworkShareCodec.Source(bytes("proxies: [&cycle {name: Cycle, type: socks5, server: 127.0.0.1, port: 1080, ignored-field: *cycle}, {name: Good, type: socks5, server: 127.0.0.1, port: 1080}]\n"));int beforeCycle=cyclic.remaining;boolean cycleRejected=false;try{cyclic.select("Entry|Cycle",NetworkCatalog.ENTRY);}catch(NetworkShareCodec.Failure expected){cycleRejected=true;}check("Cycle rejection charges inspected visits without blocking an affordable independent node",cycleRejected&&cyclic.remaining<beforeCycle&&cyclic.remaining>0&&cyclic.select("Entry|Good",NetworkCatalog.ENTRY).getInt("port")==1080);
    JSONObject result=J.obj("passed",checks.length(),"total",checks.length(),"checks",checks,"productionCandidateAndSnapshotChain",true,"nativeFingerprintVerified",false,"actualAndroidExecution",false,"scope","Production Codec.candidates/Snapshot.split/select/Codec.node/provider and reparse with synthetic native identity metadata. No native fingerprint computation, encryption or device execution.");
    if(args.length>0){Path report=Paths.get(args[0]);if(report.getParent()!=null)Files.createDirectories(report.getParent());Files.write(report,result.toString(2).getBytes(StandardCharsets.UTF_8));}System.out.println("Network share snapshot: "+checks.length()+" checks passed");
  }
}
